import { get, handleApiError, post } from '@helpers/httpClient';

import { mapBackProductUnitToFront } from '../@mappers/productUnits.mapper';
import { IProductUnitAddDTO, IProductUnitDTO } from '../@types/productUnits.backTypes';

export const addProductUnit = (data: IProductUnitAddDTO) =>
  post('/ajax/recipes/units_add.php', data).then<{ id: number }>(handleApiError);

export const listProductUnits = () =>
  get('/ajax/recipes/units_list.php')
    .then<IProductUnitDTO[]>(handleApiError)
    .then((res) => res.map(mapBackProductUnitToFront));
