import { get, handleApiError, post } from '@helpers/httpClient';

import {
  mapBackHikingFinanceCurrency,
  mapBackHikingPaymentToFront,
  mapBackHikingReceiptAddToFront,
  mapBackHikingReceiptCategory,
  mapBackHikingReceiptToFront,
  mapHikingReceiptToAddHikingReceiptDTO,
} from '../@mappers/hikingFinances.mapper';
import {
  IAddHikingReceiptDTO,
  IAddHikingReceiptDTOResult,
  IHikingPaymentDTO,
  IHikingReceiptDTO,
} from '../@types/DTO/hikingFinances.dto.types';
import {
  IHikingFinanceCurrencyDTO,
  IHikingFinancePaymentAddOrUpdateDTO,
  IHikingFinancePaymentAddOrUpdateResultDTO,
  IHikingPayment,
  IHikingReceipt,
  IHikingReceiptCategory,
} from '../@types/hikingFinances.types';

export const getHikingFinancesReceipts = async (
  criteria: { id_hiking: number } | { id: number },
) => {
  const res = await get<IHikingReceiptDTO[]>('/ajax/hiking/finance/receipts.php', criteria).then(
    handleApiError,
  );
  return res.map(mapBackHikingReceiptToFront) as IHikingReceipt[];
};

export const addOrUpdateHikingFinancesReceipt = async (
  receipt: IHikingReceipt,
  id_hiking: number,
) => {
  const data = mapHikingReceiptToAddHikingReceiptDTO(receipt, id_hiking);
  const res = await post<IAddHikingReceiptDTOResult, IAddHikingReceiptDTO>(
    '/ajax/hiking/finance/receipt_add.php',
    data,
  ).then(handleApiError);
  return mapBackHikingReceiptAddToFront(res, receipt);
};
export const updateHikingFinancesReceiptParticipation = async (
  receipt: IHikingReceipt,
  id_hiking: number,
) => {
  const res = await post('/ajax/hiking/finance/receipt_participation_update.php', {
    id_hiking,
    id_receipt: receipt.id,
    users: receipt.participation?.map((r) => r.id) ?? [],
  }).then(handleApiError);
  return !!res?.success;
};

export const deleteHikingFinancesReceipt = async (id: number, id_hiking: number) => {
  const res = await post('/ajax/hiking/finance/receipt_del.php', { id, id_hiking }).then(
    handleApiError,
  );
  return res.success as boolean;
};

export const getHikingFinancesPayments = async (id_hiking: number) => {
  const res = await get<IHikingPaymentDTO[]>('/ajax/hiking/finance/payments.php', {
    id_hiking,
  }).then(handleApiError);
  return res.map(mapBackHikingPaymentToFront) as IHikingPayment[];
};

export const addOrEditHikingFinancePayment = async (
  data: IHikingFinancePaymentAddOrUpdateDTO,
): Promise<IHikingFinancePaymentAddOrUpdateResultDTO> => {
  const res = await post('/ajax/hiking/finance/payments_add.php', data).then(handleApiError);

  return res as IHikingFinancePaymentAddOrUpdateResultDTO;
};

export const deleteHikingFinancePayment = async (
  id: number,
  id_hiking: number,
): Promise<boolean> => {
  const res = await post('/ajax/hiking/finance/payments_del.php', { id, id_hiking }).then(
    handleApiError,
  );

  return res.success;
};

export const getHikingReceiptCategories = async () => {
  const res = await get<IHikingReceiptCategory[]>(
    '/ajax/hiking/finance/receipt_categories.php',
  ).then(handleApiError);

  return res.map(mapBackHikingReceiptCategory) as IHikingReceiptCategory[];
};

export const getHikingFinanceCurrencies = async () => {
  const res = await get<IHikingFinanceCurrencyDTO[]>('/ajax/hiking/finance/currencies.php').then<
    IHikingFinanceCurrencyDTO[]
  >(handleApiError);

  return res.map(mapBackHikingFinanceCurrency);
};
