import React from 'react';

import { formatFinance } from '@helpers/formatHelper';
import { round } from '@helpers/mathHelper';
import PohAva from '@ui-kit/Ava';
import PohCol from '@ui-kit/layout/Col';
import PohRow from '@ui-kit/layout/Row';
import PohList from '@ui-kit/List';

import FinanceReceiptHTML from './FinanceReceiptHTML';
import ReceiptItems from './ReceiptItems';
import { IHikingData } from '../../@types/hiking.types';
import { IHikingReceipt } from '../../@types/hikingFinances.types';

export interface IViewReceiptModalProps {
  receipt: IHikingReceipt;
  hikingData: IHikingData;
}

const ViewReceiptModal: React.FC<IViewReceiptModalProps> = ({ receipt, hikingData }) => {
  const [showParticipation, setShowParticipation] = React.useState(true);
  return (
    <PohRow>
      <PohCol sm={6} className="mb-sm-3">
        <h1>
          {receipt.currency && receipt.totalInCurrency ? (
            <>
              <strong className="text-danger">
                {formatFinance(receipt.totalInCurrency, 2, receipt.currency.symbol)}
              </strong>
              <br />
              <small style={{ fontSize: 18 }} className="text-muted">
                {formatFinance(receipt.total)}&nbsp;по курсу{' '}
                {round(receipt.total / receipt.totalInCurrency)}
              </small>
            </>
          ) : (
            <strong className="text-danger">{formatFinance(receipt.total)}</strong>
          )}
        </h1>
        <div className="d-flex align-items-center gap-4">
          <PohAva src={receipt.user.photo} alt={receipt.user.name} />
          <div className="ms-2">
            {[receipt.user.name, receipt.user.surname].join(' ')}
            <br />
            <small>{receipt.date.toLocaleString()}</small>
          </div>
        </div>
        {receipt.participation && (
          <>
            <h4
              className="mt-4"
              role="presentation"
              onClick={() => setShowParticipation((c) => !c)}
            >
              {showParticipation ? (
                <>
                  Скидываются{' '}
                  <small className="text-warning">
                    {receipt.participation.length} из {hikingData.hikers.length}
                  </small>
                </>
              ) : (
                <>
                  Не скидываются{' '}
                  <small className="text-warning">
                    {hikingData.hikers.length - receipt.participation.length} из{' '}
                    {hikingData.hikers.length}
                  </small>
                </>
              )}
            </h4>
            <PohList
              data={hikingData.hikers
                .filter((h) =>
                  showParticipation
                    ? receipt.participation?.find((p) => h.idUser === p.id)
                    : !receipt.participation?.find((p) => h.idUser === p.id),
                )
                .map((h) => ({
                  key: h.idUser,
                  className: 'p-1',
                  disabled: !showParticipation,
                  content: (
                    <div className="d-flex align-items-center">
                      <PohAva src={h.photo[50]} alt={h.name} width={32} />
                      <div className="ms-2" style={{ lineHeight: 1 }}>
                        <b>{[h.name, h.surname].join('\u00a0')}</b>
                        <br />
                        {showParticipation ? (
                          <small className="text-muted">
                            {formatFinance(
                              Math.ceil(receipt.total / (receipt.participation?.length ?? 1)),
                              0,
                            )}
                          </small>
                        ) : (
                          <small className="text-muted">Не скидывается</small>
                        )}
                      </div>
                    </div>
                  ),
                }))}
            />
          </>
        )}
        <ReceiptItems readOnly id_hiking={hikingData.id} id_receipt={receipt.id} />
      </PohCol>
      <PohCol sm={6}>
        <label className="form-label d-flex justify-content-between">
          Изображение чека
          {receipt.pdf_url && (
            <div>
              <a href={receipt.pdf_url} target="_blank" rel="noreferrer">
                PDF-чек
              </a>
            </div>
          )}
        </label>
        <div style={{ maxHeight: '70vh', overflow: 'auto' }}>
          {receipt.images.orig && <img src={receipt.images.orig} className="w-100" />}
          {receipt.html && <FinanceReceiptHTML html={receipt.html} />}
        </div>
      </PohCol>
    </PohRow>
  );
};

export default ViewReceiptModal;
