import React, { FormEvent } from 'react';

import { addOrUpdateHikingFinancesReceiptItem } from '@apps/Hiking/@services/hikingFinancesReceiptItems.service';
import { IHikingFinanceReceiptItem } from '@apps/Hiking/@types/hikingFinances.types';
import { listProductUnits } from '@apps/Products/@services/productUnits.service';
import { IProductUnit } from '@apps/Products/@types/productUnits.types';
import { selectProductAsync } from '@apps/Products/components/ProductSelectModal/productSelectModalHelper';
import HelpInfo from '@components/HelpInfo';
import PageLoader from '@components/PageLoader';
import { formatFinance } from '@helpers/formatHelper';
import PohAlert, { AlertVariant } from '@ui-kit/Alert';
import PohButton, { ButtonVariant } from '@ui-kit/Button';
import IconsEnum from '@ui-kit/Icon/IconsEnum';
import PohInput, { InputTypes } from '@ui-kit/Input';
import PohCol from '@ui-kit/layout/Col';
import PohRow from '@ui-kit/layout/Row';
import { showModal } from '@ui-kit/Modal';
import PohSelect from '@ui-kit/Select';

const ReceiptItemsAddOrEditModal = ({
  item,
  id_receipt,
  id_hiking,
  onSave,
}: {
  item: IHikingFinanceReceiptItem;
  id_receipt: number;
  id_hiking: number;
  onSave(item: IHikingFinanceReceiptItem): void;
}) => {
  const [isSaving, setIsSaving] = React.useState(false);
  const [isLoading, setIsLoading] = React.useState(true);
  const [err, setErr] = React.useState<Error>();
  const [data, setData] = React.useState<IHikingFinanceReceiptItem>(item);
  const [units, setUnits] = React.useState<IProductUnit[]>([]);

  React.useEffect(() => {
    const start = async () => {
      try {
        setIsLoading(true);
        const d = await listProductUnits();
        setUnits(d);
      } catch (error) {
        setErr(error as Error);
      } finally {
        setIsLoading(false);
      }
    };

    start();
  }, []);

  const handleSubmit = async (e: FormEvent) => {
    e.preventDefault();
    try {
      setIsSaving(true);
      const d = await addOrUpdateHikingFinancesReceiptItem(data, id_receipt, id_hiking);
      onSave({ ...data, id: d });
    } catch (error) {
      setErr(error as Error);
    } finally {
      setIsSaving(false);
    }
  };

  function handleChange<k extends keyof IHikingFinanceReceiptItem>(fieldName: k) {
    return (value: IHikingFinanceReceiptItem[k]) =>
      setData((cur) => ({ ...cur, [fieldName]: value }));
  }

  if (isLoading) return <PageLoader />;

  return (
    <form onSubmit={handleSubmit} className="vertical-gapped" style={{ minWidth: '40vw' }}>
      <PohInput
        label="Название"
        value={data.name}
        onChange={handleChange('name')}
        autoFocus={!data.name.length}
        placeholder='Как позиция записана в чеке. Например: Конфеты "Ромашка"'
        required
      />
      <PohRow>
        <PohCol sm={data.product ? 9 : 12}>
          <PohInput
            label="Продукт"
            readOnly
            value={data.product?.name ?? ''}
            placeholder="Выбрать продукт соответствующий позиции (Не обязательно)"
            onClick={async () => {
              const selectedProduct = await selectProductAsync();
              handleChange('product')(selectedProduct);
              if (!data.name.length) {
                handleChange('name')(selectedProduct.name);
              }
            }}
            disabled={isSaving}
            after={
              <PohButton
                className="flex-shrink-0"
                icon={IconsEnum.close}
                onClick={() => {
                  handleChange('product')(null);
                  handleChange('weight')(0);
                }}
              />
            }
          />
        </PohCol>
        {data.product && (
          <PohCol sm={3}>
            <PohInput
              type={InputTypes.number}
              labelClassName="w-100"
              label={
                <div>
                  <HelpInfo className="float-end">
                    <p>
                      Укажите вес в граммах для данного варианта единицы товара. Например: сколько
                      весит пачка.
                    </p>
                    <p>Имея эти данные мы сможем подсказывать сколько пачек товара купить</p>
                  </HelpInfo>
                  Вес 1 ед. (г.)
                </div>
              }
              value={data.weight ? data.weight.toString() : ''}
              onChange={(v) => handleChange('weight')(+v)}
              step={1}
              min={0}
              max={99999}
            />
          </PohCol>
        )}
      </PohRow>

      <PohRow>
        <PohCol md={3} sm={3} xs={4}>
          <PohSelect<string>
            allowEmpty
            placeholder="-"
            options={units.map((u) => ({ label: u.short_name, value: u.id.toString() }))}
            label="Ед.изм."
            value={data.unit?.id?.toString() ?? ''}
            onChange={(v: string) =>
              handleChange('unit')(units.find((x) => x.id.toString() === v.toString()) ?? null)
            }
          />
        </PohCol>
        <PohCol md={3} sm={3} xs={4}>
          <PohInput
            label="Кол-во"
            type={InputTypes.number}
            value={data.amount ? data.amount.toString() : ''}
            onChange={(v) => handleChange('amount')(+v)}
            required
            min={0}
            step={0.001}
            max={9999}
          />
        </PohCol>
        <PohCol md={3} sm={3} xs={4}>
          <PohInput
            type={InputTypes.number}
            label="Цена 1 ед."
            value={data.cost ? data.cost.toString() : ''}
            onChange={(v) => handleChange('cost')(+v)}
            required
            min={0}
            step={0.01}
            max={99999}
          />
        </PohCol>

        <PohCol md={3} sm={3} xs={4}>
          <small className="text-muted">Сумма</small>
          <div>
            <strong className="text-danger" style={{ fontSize: '1.5em' }}>
              {formatFinance(data.cost * data.amount)}
            </strong>
          </div>
        </PohCol>
      </PohRow>
      {err && <PohAlert variant={AlertVariant.Warning}>{err.message}</PohAlert>}
      <footer className="mt-3 mb-n3 text-end">
        <PohButton variant={ButtonVariant.Primary} disabled={isSaving} type="submit">
          Сохранить
        </PohButton>
      </footer>
    </form>
  );
};

export const addOrEditHikingFinanceReceiptItemAsync = (data: {
  item: IHikingFinanceReceiptItem;
  id_receipt: number;
  id_hiking: number;
}): Promise<IHikingFinanceReceiptItem> => {
  return new Promise((res) => {
    showModal({
      title: data.item.id > 0 ? 'Редактирование позиции чека' : 'Добавление позиции чека',
      children: (clos) => {
        return (
          <ReceiptItemsAddOrEditModal
            id_hiking={data.id_hiking}
            id_receipt={data.id_receipt}
            item={data.item}
            onSave={(up) => {
              res(up);
              clos();
            }}
          />
        );
      },
    });
  });
};
