import { get, handleApiError, post } from '@helpers/httpClient';

import {
  mapFinanceReceiptItemToBackAddOrUpdate,
  mapFinanceReceiptItemToFront,
} from '../@mappers/hikingFinances.mapper';
import {
  IHikingFinanceReceiptItemDTO,
  IHikingFinanceReceiptItemsGetCriteria,
} from '../@types/DTO/hikingFinances.dto.types';
import { IHikingFinanceReceiptItem } from '../@types/hikingFinances.types';

export const getHikingFinancesReceiptItems = async (
  criteria: IHikingFinanceReceiptItemsGetCriteria,
) => {
  const res = await get('/ajax/hiking/finance/receipt_items/receipt_item_list.php', criteria).then<
    IHikingFinanceReceiptItemDTO[]
  >(handleApiError);
  return res.map(mapFinanceReceiptItemToFront);
};

export const addOrUpdateHikingFinancesReceiptItem = async (
  item: IHikingFinanceReceiptItem,
  id_receipt: number,
  id_hiking: number,
) => {
  const data = mapFinanceReceiptItemToBackAddOrUpdate(item, id_receipt, id_hiking);
  const res = await post(
    '/ajax/hiking/finance/receipt_items/receipt_item_add_or_edit.php',
    data,
  ).then<{ success: boolean; id: number }>(handleApiError);
  if (!res.success) throw new Error('Не удалось обновить');
  return res.id;
};

export const deleteHikingFinancesReceiptItem = async (id: number, id_hiking: number) => {
  const res = await post('/ajax/hiking/finance/receipt_items/receipt_item_del.php', {
    id,
    id_hiking,
  }).then(handleApiError);
  return res.success as boolean;
};

export const importHikingFinancesReceiptItems = async (
  data: { name: string; cost: number; amount: number }[],
  id_receipt: number,
  id_hiking: number,
) => {
  const res = await post('/ajax/hiking/finance/receipt_items/receipt_items_import.php', {
    id_receipt,
    id_hiking,
    data: JSON.stringify(data),
  }).then(handleApiError);
  return res.affected as number;
};
