import React from 'react';

import { getEmptyFinanceReceiptItem } from '@apps/Hiking/@mappers/hikingFinances.mapper';
import {
  deleteHikingFinancesReceiptItem,
  getHikingFinancesReceiptItems,
} from '@apps/Hiking/@services/hikingFinancesReceiptItems.service';
import { IHikingFinanceReceiptItem } from '@apps/Hiking/@types/hikingFinances.types';
import PageLoader from '@components/PageLoader';
import { formatFinance } from '@helpers/formatHelper';
import notificationHelper from '@helpers/notificationHelper';
import PohAlert, { AlertVariant } from '@ui-kit/Alert';
import PohButton, { ButtonSize } from '@ui-kit/Button';
import Empty from '@ui-kit/Empty';
import IconsEnum from '@ui-kit/Icon/IconsEnum';
import { confirmModal2 } from '@ui-kit/Modal/modalsHelper';

import { addOrEditHikingFinanceReceiptItemAsync } from './ReceiptItemsAddOrEditModal';

const ReceiptItems = ({
  id_receipt,
  id_hiking,
  readOnly = false,
}: {
  id_receipt: number;
  id_hiking: number;
  readOnly?: boolean;
}) => {
  const [isLoading, setIsLoading] = React.useState(true);
  const [err, setErr] = React.useState<Error>();
  const [data, setData] = React.useState<IHikingFinanceReceiptItem[]>([]);

  React.useEffect(() => {
    const start = async () => {
      try {
        setIsLoading(true);
        const d = await getHikingFinancesReceiptItems({ id_receipt });
        setData(d);
      } catch (error) {
        setErr(error as Error);
      } finally {
        setIsLoading(false);
      }
    };

    start();
  }, [id_receipt]);

  if (isLoading) return <PageLoader />;
  if (err) return <PohAlert variant={AlertVariant.Warning}>{err.message}</PohAlert>;

  return (
    <section>
      <header className="d-flex justify-content-between">
        <strong>Позиции из чека</strong>
        {!readOnly && (
          <PohButton
            icon={IconsEnum.plus}
            onClick={async () => {
              const newItem = await addOrEditHikingFinanceReceiptItemAsync({
                item: getEmptyFinanceReceiptItem(),
                id_receipt,
                id_hiking,
              });
              notificationHelper.success('Добавлено!');
              setData((cur) => [...cur, newItem]);
            }}
          />
        )}
      </header>
      <div className="flex-grow-1" style={{ overflowY: 'auto' }}>
        {data.length === 0 && (
          <Empty style={{ minHeight: 100 }}>
            Позиций из чека не добавлено
            <br />
            <p className="text-center px-3">
              <small>
                Добавьте позиции из чека, на основе этих данных мы сможем прогнозировать затраты
                будущих походов и подсказывать в каких вариациях можно купить тот или иной товар
              </small>
            </p>
          </Empty>
        )}
        {data.length > 0 && (
          <table className="table table-sm table-bordered table-striped w-100">
            <colgroup>
              <col width="64%" />
              <col width="12%" />
              <col width="12%" />
              <col width="12%" />
            </colgroup>
            <thead>
              <tr>
                <th>Товар</th>
                <th>Цена</th>
                <th className="text-nowrap">Кол-во</th>
                <th>Сумма</th>
              </tr>
            </thead>
            <tbody>
              {data.map((item) => {
                return (
                  <tr key={item.id} className="toolbared position-relative">
                    <td className="">
                      <small title={item.name} className="">
                        {item.name}
                      </small>
                    </td>
                    <td className="text-end">
                      <small>{item.cost.toLocaleString()}</small>
                    </td>
                    <td className="text-end">
                      <small>{item.amount.toLocaleString()}</small>
                    </td>
                    <td className="text-end">
                      <small>
                        <strong>{formatFinance(item.cost * item.amount)}</strong>
                      </small>
                      {!readOnly && (
                        <small
                          className="position-absolute show-on-hover horizontal-gapped p-1 bg-light"
                          style={{ right: 0, top: 0 }}
                        >
                          <PohButton
                            size={ButtonSize.Small}
                            icon={IconsEnum.trash}
                            onClick={async () => {
                              try {
                                const ok = await confirmModal2(`Удалить "${item.name}"?`);
                                if (!ok) return;
                                await deleteHikingFinancesReceiptItem(item.id, id_hiking);
                                notificationHelper.success('Удалено!');
                                setData((cur) => cur.filter((x) => x.id !== item.id));
                              } catch (er) {
                                notificationHelper.error((er as Error).message);
                              }
                            }}
                          />
                          <PohButton
                            size={ButtonSize.Small}
                            icon={IconsEnum.edit}
                            onClick={async () => {
                              const newItem = await addOrEditHikingFinanceReceiptItemAsync({
                                item,
                                id_receipt,
                                id_hiking,
                              });
                              notificationHelper.success('Сохранено!');
                              setData((cur) => cur.map((x) => (x.id === newItem.id ? newItem : x)));
                            }}
                          />
                        </small>
                      )}
                    </td>
                  </tr>
                );
              })}
            </tbody>
            <tfoot>
              <tr>
                <th colSpan={3} className="text-end">
                  <small>Итого:</small>
                </th>
                <th className="text-end">
                  <strong>
                    {formatFinance(
                      data.reduce((acc, val) => {
                        return acc + val.cost * val.amount;
                      }, 0),
                    )}
                  </strong>
                </th>
              </tr>
            </tfoot>
          </table>
        )}
      </div>
    </section>
  );
};

export default ReceiptItems;
